-- PostgreSQL specific: JSONB, arrays, LATERAL, regex, casts, intervals, generate_series
SELECT data->'user'->>'name' AS name, data #>> '{address,city}' AS city FROM events;
SELECT * FROM events WHERE data @> '{"type": "click"}'::jsonb;
SELECT * FROM events WHERE data ? 'user_id' AND data ?| ARRAY['a', 'b'] AND data ?& ARRAY['c', 'd'];
SELECT * FROM events WHERE (data->>'amount')::numeric > 100;
SELECT * FROM events WHERE data #> '{a,b}' = '1'::jsonb;
SELECT * FROM events WHERE '{"a": 1}'::jsonb <@ data;
SELECT data - 'password' AS safe, data || '{"x": 1}'::jsonb AS merged, data #- '{a,b}' AS removed FROM users;
SELECT jsonb_set(data, '{profile,age}', '31'::jsonb, true) FROM users;
SELECT jsonb_build_object('id', id, 'email', email) FROM users;
SELECT jsonb_agg(jsonb_build_object('sku', sku, 'qty', quantity)) FROM order_items GROUP BY order_id;
SELECT e.id, elem->>'name' FROM events e, jsonb_array_elements(e.data->'items') AS elem;
SELECT * FROM jsonb_each_text('{"a": "1", "b": "2"}'::jsonb);
SELECT * FROM events WHERE data @@ '$.items[*].price > 10';
SELECT jsonb_path_query(data, '$.items[*] ? (@.price > 10)') FROM events;
SELECT * FROM jsonb_to_recordset('[{"a": 1, "b": "x"}]'::jsonb) AS t(a int, b text);
SELECT ARRAY[1, 2, 3] || 4, ARRAY[1, 2] @> ARRAY[1], ARRAY[1, 2] && ARRAY[2, 3];
SELECT tags[1], tags[1:2], array_length(tags, 1), cardinality(tags) FROM products;
SELECT * FROM products WHERE 'sale' = ANY(tags) AND NOT ('old' = ALL(tags));
SELECT unnest(tags) AS tag, COUNT(*) FROM products GROUP BY 1;
SELECT * FROM unnest(ARRAY[1, 2, 3], ARRAY['a', 'b', 'c']) AS t(n, l);
SELECT * FROM unnest(ARRAY[10, 20]) WITH ORDINALITY AS t(val, idx);
SELECT u.id, o.* FROM users u CROSS JOIN LATERAL (SELECT * FROM orders WHERE user_id = u.id ORDER BY created_at DESC LIMIT 3) o;
SELECT u.id, o.total FROM users u LEFT JOIN LATERAL (SELECT SUM(total_cents) AS total FROM orders WHERE user_id = u.id) o ON true;
SELECT * FROM users, LATERAL jsonb_array_elements_text(u_tags) AS tag;
SELECT * FROM generate_series(1, 10) AS g(n);
SELECT d::date FROM generate_series('2024-01-01'::date, '2024-12-31'::date, INTERVAL '1 day') AS d;
SELECT g.day, COALESCE(COUNT(o.id), 0) FROM generate_series(CURRENT_DATE - 6, CURRENT_DATE, '1 day') AS g(day) LEFT JOIN orders o ON o.created_at::date = g.day GROUP BY g.day;
SELECT * FROM users WHERE name ~ '^A.*z$' AND name !~ 'test' AND email ~* '@EXAMPLE\.com$' AND email !~* 'spam';
SELECT * FROM users WHERE name SIMILAR TO '(a|b)%';
SELECT regexp_replace(phone, '[^0-9]', '', 'g'), regexp_matches(body, '(\d+)', 'g'), split_part(email, '@', 2) FROM users;
SELECT '2024-01-01'::date + INTERVAL '1 month', now() - interval '90 minutes', INTERVAL '1 year 2 months 3 days', CURRENT_TIMESTAMP AT TIME ZONE 'UTC';
SELECT created_at AT TIME ZONE 'America/New_York' FROM orders;
SELECT 1::int, '1'::text::int, CAST(price AS numeric(10, 2)), price::float8, now()::date, '{1,2}'::int[], 'abc'::varchar(2);
SELECT CAST('2024-01-01' AS timestamptz), TIMESTAMP '2024-01-01 00:00:00', DATE '2024-01-01', TIME '12:00';
SELECT EXTRACT(EPOCH FROM now()), date_part('dow', now()), age(now(), created_at), make_interval(days => 3) FROM users;
SELECT $$dollar quoted$$, $tag$ body 'with' quotes $tag$, E'tab\there', 'it''s';
SELECT u.* FROM users u WHERE u.id IS DISTINCT FROM 5 AND u.name IS NOT DISTINCT FROM NULL;
SELECT * FROM tbl WHERE (a, b) IN ((1, 2), (3, 4)) AND (c, d) > (1, 2);
SELECT ROW(1, 2) = ROW(1, 2);
SELECT * FROM users WHERE tsv @@ to_tsquery('english', 'foo & bar') ORDER BY ts_rank(tsv, to_tsquery('foo & bar')) DESC;
SELECT 'a' || 'b', 5 % 3, 2 ^ 10, |/ 25, @ -5, 7 / 2, 5 & 3, 5 | 3, 5 # 3, ~5, 1 << 3, 16 >> 2;
SELECT a <-> b FROM pts;
SELECT * FROM events WHERE ts <@ tstzrange('2024-01-01', '2024-02-01') AND during && daterange('2024-01-01', '2024-01-10');
SELECT inet '192.168.0.1' << inet '192.168.0.0/24', '10.0.0.1'::inet, macaddr '08:00:2b:01:02:03';
SELECT gen_random_uuid(), uuid_generate_v4(), md5('x'), encode(digest('x', 'sha256'), 'hex');
SELECT current_user, session_user, current_schema(), current_setting('search_path'), pg_typeof(1), version();
SELECT col COLLATE "C" FROM t ORDER BY name COLLATE "en_US";
SELECT * FROM ONLY parent_tbl;
SELECT * FROM t WHERE x = ANY (SELECT y FROM u) AND z <> ALL (SELECT w FROM v);
SELECT count(*) OVER () FROM t LIMIT ALL OFFSET 5 ROWS;
SELECT * FROM t ORDER BY id FETCH FIRST 5 ROWS WITH TIES;
SELECT * FROM t OFFSET 10 LIMIT 5;
VALUES (1, 'a'), (2, 'b');
SELECT * FROM (VALUES (1, 'a'), (2, 'b')) AS v(id, name);
TABLE users;
SELECT 1 WHERE EXISTS (SELECT 1) AND NOT EXISTS (SELECT 2);
SELECT * INTO new_tbl FROM old_tbl WHERE x > 1;
